import { eq, and, isNull, not, inArray } from "drizzle-orm";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const IMAGES_DIR = path.join(__dirname, "seeds", "images");
// Imagens importadas do lote do usuário. Esta pasta tem prioridade sobre as imagens legadas.
const IMPORTED_IMAGES_DIR = path.join(IMAGES_DIR, "imported");
const IMPORTED_MANUAL_KEYS_FILE = path.join(IMPORTED_IMAGES_DIR, "manual_keys.json");
const SPIRIT_ITEMS_DIR = path.join(__dirname, "seeds", "spirit_items");
const UNNAMED_TEMP_DIR = path.join(__dirname, "seeds", "unnamed_temp");
// Imagens do jogo Expo — fonte adicional de imagens de Digimon
const EXPO_IMAGES_DIR = path.join(__dirname, "..", "..", "omega-dx10", "assets", "images", "digimons");

function readImage(filename: string): { base64: string; mime: string } | null {
  const filepath = [
    path.join(EXPO_IMAGES_DIR, filename),
    path.join(IMPORTED_IMAGES_DIR, filename),
  ]
    .find((candidate) => fs.existsSync(candidate));
  if (!filepath) return null;
  const ext = path.extname(filename).toLowerCase();
  const mime = ext === ".webp" ? "image/webp" : ext === ".png" ? "image/png" : "image/gif";
  return { base64: fs.readFileSync(filepath).toString("base64"), mime };
}

function readImageFromPath(filepath: string): { base64: string; mime: string } | null {
  if (!fs.existsSync(filepath)) return null;
  const ext = path.extname(filepath).toLowerCase();
  const mime = ext === ".webp" ? "image/webp" : ext === ".png" ? "image/png" : "image/gif";
  return { base64: fs.readFileSync(filepath).toString("base64"), mime };
}

// ─── Helper: garante um digimon na coleção do usuário ────────────────────────
async function ensureDigimonInCollection(
  userId: number,
  characterId: string,
  level = 1,
): Promise<void> {
  const [save] = await db.select().from(gameSavesTable).where(eq(gameSavesTable.userId, userId)).limit(1);
  type OwnedEntry = { ownedId: string; characterId: string; level: number; exp: number };
  const current = (save?.saveData as Record<string, unknown>) ?? {};
  const collection = (current.collection ?? []) as OwnedEntry[];
  const already = collection.some((c) => c.characterId === characterId);
  if (already) return;
  const ownedId = `seed_${characterId}_${userId}`;
  const updated = [...collection, { ownedId, characterId, level, exp: 0 }];
  if (save) {
    await db.update(gameSavesTable)
      .set({ saveData: { ...current, collection: updated }, updatedAt: new Date() })
      .where(eq(gameSavesTable.userId, userId));
  } else {
    await db.insert(gameSavesTable).values({ userId, saveData: { tamerLevel: 1, collection: updated }, updatedAt: new Date() });
  }
}

// ─── Helper: garante tamerLevel mínimo no saveData ───────────────────────────
async function ensureTamerLevel(userId: number, level: number): Promise<void> {
  const [save] = await db.select().from(gameSavesTable).where(eq(gameSavesTable.userId, userId)).limit(1);
  if (save) {
    const current = (save.saveData as Record<string, unknown>) ?? {};
    if ((current.tamerLevel as number ?? 0) < level) {
      await db.update(gameSavesTable)
        .set({ saveData: { ...current, tamerLevel: level }, updatedAt: new Date() })
        .where(eq(gameSavesTable.userId, userId));
      console.log(`[seed] tamerLevel → ${level} (userId=${userId})`);
    }
  } else {
    await db.insert(gameSavesTable).values({ userId, saveData: { tamerLevel: level }, updatedAt: new Date() });
    console.log(`[seed] Save criado com tamerLevel=${level} (userId=${userId})`);
  }
}

