// ─── Desativa Digimons sem imagem ─────────────────────────────────────────────
export async function deactivateDigimonsWithoutImage(): Promise<void> {
  try {
    // Raridades que são válidas mesmo sem imagem (ovos, bebês, treinamento)
    const EXEMPT_RARITIES = ["EGG", "BABY", "TRAINING"];
    await db
      .update(customDigimonsTable)
      .set({ isActive: false, updatedAt: new Date() })
      .where(
        and(
          eq(customDigimonsTable.isActive, true),
          isNull(customDigimonsTable.imageBase64),
          not(inArray(customDigimonsTable.rarity as any, EXEMPT_RARITIES)),
        )
      );
    // Garante que ovos, bebês e formas de treinamento sempre ficam ativos
    await db
      .update(customDigimonsTable)
      .set({ isActive: true, updatedAt: new Date() })
      .where(inArray(customDigimonsTable.rarity as any, EXEMPT_RARITIES));
    console.log("[seed] Digimons sem imagem desativados (exceto EGG/BABY/TRAINING).");
  } catch (err) {
    console.error("[seed] Erro ao desativar Digimons sem imagem:", err);
  }
}

