// Corrige evolvesFromId inválidos (referências legadas com chave base ou custom_0)
// Usa nomes para identificar tanto o filho quanto o pai — portável entre ambientes.
export async function fixBrokenEvolvesFromIds(): Promise<void> {
  try {
    const rows = await db
      .select({ id: customDigimonsTable.id, name: customDigimonsTable.name, evolvesFromId: customDigimonsTable.evolvesFromId })
      .from(customDigimonsTable);

    const byName: Record<string, number> = Object.fromEntries(rows.map(r => [r.name.toLowerCase(), r.id]));
    const byId: Record<number, string> = Object.fromEntries(rows.map(r => [r.id, `custom_${r.id}`]));

    // childName → correctParentName (both resolved from DB)
    const fixes: { childName: string; parentName: string }[] = [
      { childName: 'Piddomon',          parentName: 'Patamon' },
      { childName: 'MasterTyrannomon',  parentName: 'Tyrannomon' },
      { childName: 'Examon',            parentName: 'Groundramon' },
      { childName: 'Leopardmon',        parentName: 'LoaderLiomon' },
      { childName: 'Strikedramon',      parentName: 'Monodramon' },
    ];

    let fixed = 0;
    for (const { childName, parentName } of fixes) {
      const childId = byName[childName.toLowerCase()];
      const parentId = byName[parentName.toLowerCase()];
      if (!childId || !parentId) continue;

      const correctRef = `custom_${parentId}`;
      const child = rows.find(r => r.id === childId);
      // Only update if current value is wrong (legacy string or custom_0)
      if (!child || child.evolvesFromId === correctRef) continue;

      const currentRef = child.evolvesFromId ?? '';
      const isInvalid = currentRef === 'custom_0' || !currentRef.startsWith('custom_') || !(Number(currentRef.replace('custom_', '')) in byId);
      if (!isInvalid) continue;

      const result = await db.update(customDigimonsTable)
        .set({ evolvesFromId: correctRef, updatedAt: new Date() })
        .where(eq(customDigimonsTable.id, childId))
        .returning({ id: customDigimonsTable.id });

      if (result.length > 0) fixed++;
    }
    if (fixed > 0) console.log(`[seed] evolvesFromId corrigidos: ${fixed} Digimons.`);
  } catch (err) {
    console.error("[seed] Erro ao corrigir evolvesFromId:", err);
  }
}

