// ─── Seed dos 20 Spirit Items (Espíritos Lendários do Frontier) ──────────────
export async function seedSpiritItems(): Promise<void> {
  try {
    function readSpiritImage(filename: string): { base64: string; mime: string } | null {
      const fp = path.join(SPIRIT_ITEMS_DIR, filename);
      if (!fs.existsSync(fp)) return null;
      const ext = path.extname(filename).toLowerCase();
      const mime = ext === ".webp" ? "image/webp" : ext === ".png" ? "image/png" : "image/gif";
      return { base64: fs.readFileSync(fp).toString("base64"), mime };
    }

    const SPIRIT_ITEMS: Array<{
      name: string; type: string; slot: string | null; description: string; rarity: string;
      howToObtain: string; bonuses: object; imageFile: string | null;
    }> = [
      { name: "Spirit Humano do Fogo",      type: "fragment", slot: null, description: "Espírito Humano do Fogo — obtido sacrificando Agnimon. Representa a chama do guerreiro Takuya.",       rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_fogo.webp" },
      { name: "Spirit Besta do Fogo",        type: "fragment", slot: null, description: "Espírito Besta do Fogo — obtido sacrificando BurningGreymon. Representa o dragão flamejante.",         rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_fogo.webp" },
      { name: "Spirit Humano do Vento",      type: "fragment", slot: null, description: "Espírito Humano do Vento — obtido sacrificando Kazemon. Representa a fada dos ventos Zoe.",            rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_vento.webp" },
      { name: "Spirit Besta do Vento",       type: "fragment", slot: null, description: "Espírito Besta do Vento — obtido sacrificando Zephyrmon. Representa a harpia dos ventos.",             rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_vento.webp" },
      { name: "Spirit Humano do Raio",       type: "fragment", slot: null, description: "Espírito Humano do Raio — obtido sacrificando Beetlemon. Representa o besouro trovejante JP.",         rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_raio.webp" },
      { name: "Spirit Besta do Raio",        type: "fragment", slot: null, description: "Espírito Besta do Raio — obtido sacrificando MetalKabuterimon. Representa o titã metálico do trovão.", rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_raio.webp" },
      { name: "Spirit Humano da Luz",        type: "fragment", slot: null, description: "Espírito Humano da Luz — obtido sacrificando Lobomon. Representa o lobo guerreiro da luz Koji.",       rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_luz.webp" },
      { name: "Spirit Besta da Luz",         type: "fragment", slot: null, description: "Espírito Besta da Luz — obtido sacrificando KendoGarurumon. Representa o lobo laser da luz.",          rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_luz.webp" },
      { name: "Spirit Humano do Gelo",       type: "fragment", slot: null, description: "Espírito Humano do Gelo — obtido sacrificando Kumamon/Chakmon. Representa o urso polar Tommy.",        rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_gelo.webp" },
      { name: "Spirit Besta do Gelo",        type: "fragment", slot: null, description: "Espírito Besta do Gelo — obtido sacrificando Korikakumon. Representa o colosso de gelo.",              rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_gelo.webp" },
      { name: "Spirit Humano da Escuridão",  type: "fragment", slot: null, description: "Espírito Humano da Escuridão — obtido sacrificando Loweemon. Representa o leão das trevas Koji.",     rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_escuridao.webp" },
      { name: "Spirit Besta da Escuridão",   type: "fragment", slot: null, description: "Espírito Besta da Escuridão — obtido sacrificando KaiserLeomon. Representa o rei das trevas.",         rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_escuridao.webp" },
      { name: "Spirit Humano da Água",       type: "fragment", slot: null, description: "Espírito Humano da Água — obtido sacrificando Ranamon. Representa a ninfa das águas Zoe.",             rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_agua.webp" },
      { name: "Spirit Besta da Água",        type: "fragment", slot: null, description: "Espírito Besta da Água — obtido sacrificando Calmaramon. Representa a besta abissal das águas.",       rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_agua.webp" },
      { name: "Spirit Humano da Terra",      type: "fragment", slot: null, description: "Espírito Humano da Terra — obtido sacrificando Grumblemon. Representa o gnomo brutamontes da terra.",  rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_terra.webp" },
      { name: "Spirit Besta da Terra",       type: "fragment", slot: null, description: "Espírito Besta da Terra — obtido sacrificando Gigasmon. Representa o titã de pedra da terra.",         rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_terra.webp" },
      { name: "Spirit Humano da Madeira",    type: "fragment", slot: null, description: "Espírito Humano da Madeira — obtido sacrificando Arbormon. Representa o boneco de madeira Koichi.",    rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_humano_madeira.webp" },
      { name: "Spirit Besta da Madeira",     type: "fragment", slot: null, description: "Espírito Besta da Madeira — obtido sacrificando Petaldramon. Representa o dragão de pétalas.",         rarity: "EPIC",      howToObtain: "drop", bonuses: {}, imageFile: "spirit_besta_madeira.webp" },
      { name: "Spirit Humano do Metal",      type: "fragment", slot: null, description: "Espírito Humano do Metal — raro espírito de aço dos Guerreiros Antigos.",                               rarity: "LEGENDARY", howToObtain: "admin", bonuses: {}, imageFile: "spirit_humano_metal.webp" },
      { name: "Spirit Besta do Metal",       type: "fragment", slot: null, description: "Espírito Besta do Metal — raro espírito de titânio dos Guerreiros Antigos.",                           rarity: "LEGENDARY", howToObtain: "admin", bonuses: {}, imageFile: "spirit_besta_metal.webp" },
    ];

    let added = 0;
    for (const item of SPIRIT_ITEMS) {
      const existing = await db.select({ id: customItemsTable.id }).from(customItemsTable).where(eq(customItemsTable.name, item.name)).limit(1);
      if (existing.length > 0) continue;
      const img = item.imageFile ? readSpiritImage(item.imageFile) : null;
      await db.insert(customItemsTable).values({
        name: item.name, type: item.type, slot: item.slot,
        description: item.description, rarity: item.rarity,
        howToObtain: item.howToObtain, bonuses: item.bonuses,
        isActive: true,
        imageBase64: img?.base64 ?? null,
        imageMimeType: img?.mime ?? null,
      });
      added++;
    }
    if (added > 0) console.log(`[seed] Spirit Items criados: ${added}`);
  } catch (err) {
    console.error("[seed] Erro ao criar spirit items:", err);
  }
}

// Auto-vincula imagens a Digimons pelo nome do arquivo.
// O lote importado tem prioridade e substitui imagens anteriores; nomes ambíguos
// devem ser resolvidos antes de entrar em seeds/images/imported/.
export async function syncImagesFromFolder(): Promise<void> {
  try {
    const allDigimons = await db
      .select({ id: customDigimonsTable.id, name: customDigimonsTable.name })
      .from(customDigimonsTable);

    if (allDigimons.length === 0) return;

    // Mapa: nome normalizado → Digimon. Só há correspondência automática quando
    // existe um único nome cadastrado para a chave normalizada.
    const norm = (s: string) => s.replace(/[^a-zA-Z0-9]/g, "").toLowerCase();
    const digiByNorm = new Map<string, { id: number; name: string }[]>();
    for (const row of allDigimons) {
      const key = norm(row.name);
      const rows = digiByNorm.get(key) ?? [];
      rows.push(row);
      digiByNorm.set(key, rows);
    }

    // Coleta arquivos de todas as pastas de imagem disponíveis.
    // O lote novo do app é a fonte canônica. A pasta imported contém apenas
    // decisões manuais confirmadas para nomes que não estão no lote.
    const VALID_EXTS = [".gif", ".webp", ".png", ".jpg", ".jpeg"];
    const allFiles: { fullPath: string; filename: string }[] = [];
    const manualKeys = new Set<string>(
      fs.existsSync(IMPORTED_MANUAL_KEYS_FILE)
        ? JSON.parse(fs.readFileSync(IMPORTED_MANUAL_KEYS_FILE, "utf8"))
        : [],
    );

    for (const dir of [EXPO_IMAGES_DIR, IMPORTED_IMAGES_DIR]) {
      if (!fs.existsSync(dir)) continue;
      for (const f of fs.readdirSync(dir)) {
        if (VALID_EXTS.includes(path.extname(f).toLowerCase())) {
          allFiles.push({ fullPath: path.join(dir, f), filename: f });
        }
      }
    }

    // Match por nome normalizado, sem sufixos heurísticos. A pasta importada já
    // contém apenas os nomes/correções escolhidos para este lote.
    const exactMatches = new Map<number, { filename: string; img: { base64: string; mime: string } }>();
    for (const { fullPath, filename } of allFiles) {
      const ext = path.extname(filename).toLowerCase();
      const baseName = norm(path.basename(filename, ext));
      if (manualKeys.has(baseName)) continue;
      const matches = digiByNorm.get(baseName);
      if (matches?.length !== 1) continue;
      const matched = matches[0];
      if (!exactMatches.has(matched.id)) {
        const img = readImageFromPath(fullPath);
        if (img) exactMatches.set(matched.id, { filename, img });
      }
    }

    // Aplica matches
    let updated = 0;
    for (const [id, { filename, img }] of exactMatches) {
      const row = allDigimons.find(r => r.id === id)!;
      await db
        .update(customDigimonsTable)
        .set({ imageBase64: img.base64, imageMimeType: img.mime, isActive: true, updatedAt: new Date() })
        .where(eq(customDigimonsTable.id, id));
      console.log(`[seed] Imagem vinculada: ${filename} → ${row.name} (id=${id})`);
      updated++;
      digiByNorm.delete(norm(row.name));
    }

    if (updated > 0) console.log(`[seed] Total de imagens vinculadas: ${updated}`);
  } catch (err) {
    console.error("[seed] Erro ao sincronizar imagens da pasta:", err);
  }
}

// Vincula imagens da pasta unnamed_temp pelo ID do arquivo (imageNNN.png → Digimon id=NNN)
export async function syncImagesFromTempFolder(): Promise<void> {
  try {
    if (!fs.existsSync(UNNAMED_TEMP_DIR)) return;
    const files = fs.readdirSync(UNNAMED_TEMP_DIR);
    let updated = 0;
    for (const file of files) {
      const match = file.match(/^image(\d+)\.png$/);
      if (!match) continue;
      const id = parseInt(match[1]);
      const [row] = await db
        .select({ id: customDigimonsTable.id, name: customDigimonsTable.name, img: customDigimonsTable.imageBase64 })
        .from(customDigimonsTable)
        .where(eq(customDigimonsTable.id, id))
        .limit(1);
      if (!row || row.img) continue;
      const filepath = path.join(UNNAMED_TEMP_DIR, file);
      const base64 = fs.readFileSync(filepath).toString("base64");
      await db.update(customDigimonsTable)
        .set({ imageBase64: base64, imageMimeType: "image/png", updatedAt: new Date() })
        .where(eq(customDigimonsTable.id, id));
      console.log(`[seed] Imagem (temp) vinculada: ${file} → ${row.name} (id=${id})`);
      updated++;
    }
    if (updated > 0) console.log(`[seed] Total de imagens (temp) vinculadas: ${updated}`);
  } catch (err) {
    console.error("[seed] Erro ao sincronizar imagens da pasta temp:", err);
  }
}
